public class InheritancePointTester2 {
	public static void main(String[] args) {
		Point p = new Point(1, 2);
		p.translate(5, 1);
	    System.out.println(p);
	    Point3D p3d = new Point3D(11, 12, 13);
	    p3d.translate(5, 1, 3);
	    System.out.println(p3d);  
	}
}
//Khatwa 1: Ta3rif al-fasl Point
class Point {
	//Khatwa 1.1: I3lan al-mutaghayyirat al-instance
	private int x;
	private int y;
	//Khatwa 1.2: Ta3rif al-constructor li-insha nuqta bi-isaalat xy al-muwayyana
	public Point(int x, int y) {
		this.x = x;
	    this.y = y;
	}
	//Khatwa 1.3: I3lan al-method li-ta7riek makan al-nuqta bi-l-mablagh al-mawduh
	public void translate(int dx, int dy) {
		x += dx;
		y += dy;
	}
	//Khatwa 1.4: Ta3rif al-toString method li-ikhraj tamthil nassei li-instans Point
	public String toString() {
	    return "(" + x + ", " + y + ")";
	}
	//Khatwa 1.5: Ta3rif al-methods li-husul 3ala iska xy al-nuqta
	public int getX() {
		return x;
	}
	public int getY() {
		return y;
	}		
}
//Khatwa 2: Tawsia al-fasl Point li-ta3rif al-fasl Point3D
class Point3D extends Point {
	//Khatwa 2.1: I3lan al-mutaghayyir al-instance
	private int z;
	//Khatwa 2.2: Ta3rif al-constructor li-insha nuqta 3D bi-isaalat xyz al-muwayyana
	public Point3D(int x, int y, int z) {
		super(x, y);
	    this.z = z;
	}
	//Khatwa 1.3: I3lan al-method li-ta7riek makan al-nuqta fi al-fada' 3D bi-l-mablagh al-muwayyan
	public void translate(int dx, int dy, int dz) {
	    super.translate(dx, dy);
	    z += dz;
	}
	//Khatwa 1.4: Ta3rif al-method li-husul 3ala iska z li-nuqta 3D
	public int getZ() {
		return z;
	}	
	//Khatwa 1.5: Override li-toString method min fasl Point li-ikhraj tamthil nassei li-instans Point3D
	public String toString() {
	    return "(" + super.getX() + "," + super.getY() + "," + this.z + ")";
	}
}
